final class Node {
  @volatile private var x = 0.0
  @volatile private var world: Option[World] = None     // None == dirty

  def move(dx: Double): Unit = synchronized { x += dx; world = None }

  def currentWorld: World =
    world.getOrElse(synchronized {
      world.getOrElse { world = Some(compute(x)); world.get }
    })
}
